import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"故障排查","description":"CertHub 常见故障速查：DNS 验证、证书不生效、日志不实时、定时不触发、登录问题与数据目录异常。","frontmatter":{"title":"故障排查","description":"CertHub 常见故障速查：DNS 验证、证书不生效、日志不实时、定时不触发、登录问题与数据目录异常。"},"headers":[],"relativePath":"docs/troubleshoot.md","filePath":"docs/troubleshoot.md","lastUpdated":null}'),o={name:"docs/troubleshoot.md"};function h(c,t,s,i,n,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><h2 id="先看这三个地方" tabindex="-1">先看这三个地方 <a class="header-anchor" href="#先看这三个地方" aria-label="Permalink to &quot;先看这三个地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>能看出什么</th></tr></thead><tbody><tr><td><strong>执行历史 → 查看日志</strong></td><td>失败在哪个任务、哪一步、对端返回了什么</td></tr><tr><td><code>backend.log</code> / 容器日志</td><td>启动异常、数据库、调度器、未处理错误</td></tr><tr><td><code>GET /api/health</code></td><td>数据库、磁盘、调度器是否正常（异常返回 503）</td></tr></tbody></table><p>业务性异常（<code>PipelineError</code> / <code>DeployError</code> / <code>AcmeError</code> / <code>NotifyError</code> / <code>DnsError</code> 等）<strong>不会打堆栈</strong>，日志里只有一行中文结论；云厂商错误压成 <code>[Code] Message</code> 一行。</p><h2 id="证书申请" tabindex="-1">证书申请 <a class="header-anchor" href="#证书申请" aria-label="Permalink to &quot;证书申请&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>Did not find challenge value</code> / <code>incorrectResponse</code></td><td>DNS 记录还没生效就通知了 CA</td><td>任务里把「DNS 传播等待」调到 300~600 秒，或加大「传播校验重试次数」</td></tr><tr><td>DNS 验证一直等待生效</td><td>AK 没有该域名的解析权限，或域名不在这个账号下</td><td>用最小权限子账号，确认域名的权威 NS 指向这家服务商</td></tr><tr><td>提示「未到续期时间」</td><td>剩余天数大于 <code>renewDays</code>（默认 20）</td><td>调小「提前续期天数」，或打开「强制续期」</td></tr><tr><td><code>Unknown external account binding (EAB) key</code></td><td>Google EAB 过期（7 天）</td><td>授权管理里更新 EAB 凭据后重跑</td></tr><tr><td><code>External account binding has already been used</code></td><td>一次性 EAB 被复用（FreeSSL / LiteSSL）</td><td>轮换一份新 EAB</td></tr><tr><td><code>The bound account does not exist</code></td><td>EAB 与所选 CA 不匹配</td><td>确认 EAB 授权的「所属 CA」选对，重新取一份 EAB</td></tr><tr><td>访问 Google / ZeroSSL 超时、<code>WinError 10054</code></td><td>国内网络</td><td>系统设置 → 网络设置：填 HTTP 代理，或给 CA 配反向代理域名</td></tr><tr><td>泛域名验证失败</td><td>用了 HTTP-01</td><td>泛域名只能用 DNS-01</td></tr><tr><td>CAA 记录导致签发被拒</td><td>域名有严格 CAA</td><td>把 <code>trustasia.com</code>（LiteSSL）/ 对应 CA 的 CAA 身份加进去</td></tr><tr><td>免费证书报额度不足</td><td>云厂商免费额度用尽</td><td>换 CA 或走 ACME</td></tr></tbody></table><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>流水线成功，但站点还是旧证书</td><td>部署路径不对 / 没重载 / 浏览器缓存</td><td>证书库里确认证书是新的；检查 <code>certPath</code> 与 <code>reloadCmd</code>；部分面板需要手动重载</td></tr><tr><td>报「需要「群晖 DSM」类型的授权，当前选的是「宝塔面板」」</td><td>授权类型与插件不匹配</td><td>在任务里改选正确类型的授权</td></tr><tr><td>群晖登录失败</td><td>设备 ID 过期（约 30 天）或未开启「信任设备跳过双重验证」</td><td>重新点「获取设备 ID」；或在授权里配「验证密钥」由系统自动回退</td></tr><tr><td>权限不足 / 写不进目录</td><td>SSH 账号无写权限</td><td>换有权限的账号，或给 sudoers 放行重载命令</td></tr><tr><td>CDN 已更新但访问还是旧证书</td><td>CDN 生效延迟</td><td>等几分钟；必要时在云控制台刷新证书绑定</td></tr></tbody></table><h2 id="界面与日志" tabindex="-1">界面与日志 <a class="header-anchor" href="#界面与日志" aria-label="Permalink to &quot;界面与日志&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>执行日志不实时、一直转圈</td><td>反向代理开了 buffering</td><td>Nginx 加 <code>proxy_buffering off;</code> 与 <code>proxy_read_timeout 3600s;</code></td></tr><tr><td>页面显示旧内容</td><td>浏览器缓存了旧 bundle</td><td><code>Ctrl + F5</code>；确认 <code>frontend/dist</code> 是构建后的产物</td></tr><tr><td>日志里有 <code>status=running</code> 的僵尸记录</td><td>进程被强杀</td><td>重启服务，启动时会把它们标成 <code>failed</code> 并补一句「服务重启，本次执行已中断」</td></tr><tr><td>点「停止」后还在跑一会儿</td><td>协作式停止，只在任务边界检查标志位</td><td>正常现象，等当前 HTTP 请求结束</td></tr></tbody></table><h2 id="定时任务" tabindex="-1">定时任务 <a class="header-anchor" href="#定时任务" aria-label="Permalink to &quot;定时任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>到点不触发</td><td>调度器没起来 / 时区不对</td><td>看 <code>/api/health</code> 的 <code>scheduler</code>；确认 <code>CERTD_TZ=Asia/Shanghai</code></td></tr><tr><td>改了 cron 但下次运行时间没变</td><td>服务端会立即重算，前端需刷新</td><td>刷新页面；仍不对就看系统设置里的时区</td></tr><tr><td>停用后仍显示下次运行时间</td><td>老数据</td><td>重新启用再停用一次即可重算</td></tr></tbody></table><h2 id="登录与账号" tabindex="-1">登录与账号 <a class="header-anchor" href="#登录与账号" aria-label="Permalink to &quot;登录与账号&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>提示「当前未开放注册」</td><td>自助注册默认关闭</td><td>系统设置 → 站点信息 打开，或由管理员建号</td></tr><tr><td>账号被锁</td><td>连续失败 5 次，锁 10 分钟</td><td>等 10 分钟，或管理员在用户管理里重置密码（会清除锁定）</td></tr><tr><td>管理员密码忘了</td><td>没有邮件找回</td><td>管理员重置；单账号场景见下方「重置密码」</td></tr><tr><td>登录态全部失效</td><td><code>data/secret.key</code> 被删 / 换机没带过来</td><td>恢复备份里的 <code>secret.key</code></td></tr></tbody></table><h3 id="重置密码-有另一台机器可用时" tabindex="-1">重置密码（有另一台机器可用时） <a class="header-anchor" href="#重置密码-有另一台机器可用时" aria-label="Permalink to &quot;重置密码（有另一台机器可用时）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import sys;sys.path.insert(0,&#39;backend&#39;);from app.security import hash_password;print(hash_password(&#39;新密码&#39;))&quot;</span></span></code></pre></div><p>把结果写进 <code>user</code> 表的 <code>password</code> 字段，同时把 <code>login_fail_count</code> 置 0、<code>locked_until</code> 置 NULL。</p><h2 id="数据与磁盘" tabindex="-1">数据与磁盘 <a class="header-anchor" href="#数据与磁盘" aria-label="Permalink to &quot;数据与磁盘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>数据目录暴涨</td><td>历史记录 + 证书文件累积</td><td>调小执行历史保留条数，清理 <code>data/certs</code> 旧目录与旧备份</td></tr><tr><td>启动报磁盘不足 / 健康检查 503</td><td>剩余空间 &lt; 200MB</td><td>清理磁盘，或迁移数据目录到更大的分区</td></tr><tr><td>换机器后凭据都解不开</td><td>没带 <code>secret.key</code></td><td>从备份恢复 <code>secret.key</code> 后重启</td></tr></tbody></table><h2 id="还是解决不了" tabindex="-1">还是解决不了？ <a class="header-anchor" href="#还是解决不了" aria-label="Permalink to &quot;还是解决不了？&quot;">​</a></h2><p>提 issue 时请带上：<strong>执行历史里的完整日志</strong>（含阶段标题）、CertHub 版本、部署方式（源码 / Docker）、涉及的插件类型。日志里的凭据已被脱敏，可以放心贴。</p>',21)])])}const p=d(o,[["render",h]]);export{u as __pageData,p as default};
